final readonly class UrlRewriteApiController{public function __construct(private JsonResponder $json,private PersonalAccessTokenAuthenticator $auth,private UrlRewriteRepository $rewrites,private UrlRewriteMutationService $mutations,private UrlRewriteLifecycleCoordinator $lifecycle){}public function index(Request $r):Response{$p=$this->principal($r,'url_rewrites:read');if($p instanceof Response)return$p;$site=$r->siteContext()?->siteId;if($site===null)return$this->json->error('site_not_found','No active Site exists for this host.',404);return$this->json->success(['url_rewrites'=>array_map($this->row(...),$this->rewrites->allForSite($site))]);}public function show(Request $r):Response{$p=$this->principal($r,'url_rewrites:read');if($p instanceof Response)return$p;$x=$this->rewrite($r);return$x===null?$this->json->error('url_rewrite_not_found','URL Rewrite does not exist for this Site.',404):$this->json->success(['url_rewrite'=>$this->row($x)]);}public function create(Request $r):Response{return$this->save($r,null);}public function update(Request $r):Response{$x=$this->rewrite($r);return$x===null?$this->json->error('url_rewrite_not_found','URL Rewrite does not exist for this Site.',404):$this->save($r,$x);}public function disable(Request $r):Response{return$this->life($r,'disable');}public function restore(Request $r):Response{return$this->life($r,'restore');}public function deletePermanently(Request $r):Response{return$this->life($r,'delete');}private function save(Request $r,?UrlRewrite $existing):Response{$p=$this->principal($r,'url_rewrites:write');if($p instanceof Response)return$p;$site=$r->siteContext()?->siteId;if($site===null)return$this->json->error('site_not_found','No active Site exists for this host.',404);try{$x=$this->mutations->save($site,$existing,$r->json(),$p->user->id,$p->user->email);}catch(InvalidArgumentException|PDOException $e){return$this->json->error('invalid_url_rewrite',$e->getMessage(),422);}return$this->json->success(['url_rewrite'=>$this->row($x)],$existing===null?201:200);}private function life(Request $r,string $op):Response{$p=$this->principal($r,'url_rewrites:write');if($p instanceof Response)return$p;$x=$this->rewrite($r);if($x===null)return$this->json->error('url_rewrite_not_found','URL Rewrite does not exist for this Site.',404);$result=match($op){'disable'=>$this->lifecycle->disable($x,$p->user->id,$p->user->email),'restore'=>$this->lifecycle->restore($x,$p->user->id,$p->user->email),'delete'=>$this->lifecycle->deletePermanently($x,$p->user->id,$p->user->email)};if(!$result->successful)return$this->json->error('url_rewrite_lifecycle_blocked',$result->message??'URL Rewrite lifecycle operation was blocked.',409,['blockers'=>$result->blockers]);if($op==='delete')return$this->json->success(['deleted'=>true,'url_rewrite_id'=>$x->id]);return$this->json->success(['url_rewrite'=>$this->row($this->rewrites->findByIdForSite($x->id,$x->siteId))]);}private function rewrite(Request $r):?UrlRewrite{$site=$r->siteContext()?->siteId;return$site===null?null:$this->rewrites->findByIdForSite((int)$r->routeParam('id','0'),$site);}private function principal(Request $r,string $scope):PersonalAccessTokenPrincipal|Response{$p=$this->auth->authenticate($r->header('authorization'));if($p===null)return$this->json->error('invalid_bearer_token','A valid bearer token is required.',401);if(!$p->allows($scope)||!$p->user->can('settings.manage'))return$this->json->error('insufficient_scope','The bearer token cannot perform this URL Rewrite operation.',403);return$p;}private function row(?UrlRewrite $x):array{return$x===null?[]:['id'=>$x->id,'site_id'=>$x->siteId,'request_path'=>'/'.$x->requestPath,'target_path'=>$x->targetPath,'redirect_type'=>$x->redirectType,'active'=>$x->isActive,'entity_type'=>$x->entityType,'entity_id'=>$x->entityId];}}
